import useFetchData from "./useFetchData";

const C2 = () => {
  const { data: properties, loading } = useFetchData("/properties.json");

  if (loading) return <div>Loading...</div>;

  return (
    <>
      {/* Header */}
      <p className="font-semibold text-2xl md:text-5xl text-center md:mb-4">
        Compass Exclusives
      </p>
      <p className="text-center text-lg text-gray-600">
        Be the first to browse exclusive listings before they hit the market
      </p>

      {/* Listings */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 mt-6">
        {properties.map((property) => (
          <div
            key={property.id}
            className="relative bg-white rounded-lg shadow-md overflow-hidden hover:border border-blue-500"
          >
            {/* Image */}
            <img
              src={property.img}
              alt={`Listing ${property.id}`}
              className="w-full h-[250px] object-cover"
            />
            
            {/* Tag */}
            <span className="absolute top-2 left-2 bg-black text-white text-sm font-semibold px-3 py-1 rounded">
              COMPASS COMING SOON
            </span>

            {/* Details */}
            <div className="p-4">
              <p className="text-lg font-bold">{property.price}</p>
              <p className="text-sm text-gray-600">{property.location}</p>
              <div className="flex justify-between text-gray-500 text-sm mt-2">
                <p>{property.beds} Beds</p>
                <p>{property.baths} Baths</p>
                <p>{property.sqft}</p>
              </div>
            </div>
          </div>
        ))}
      </div>
    </>
  );
};

export default C2;
